/// <summary>
/// Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
/// </summary>
[ExtensionOf(classStr(TAMRebateQueryBuilder))]
final class METTAMRebateQueryBuilder_Extension
{
    // Variable to identify if provision or rebate
    private TAMRebateTransactionType metRebateTransactionType;
}

Method.Source:
/// <summary>
/// Parm method for the rebate transaction type
/// </summary>
/// <param name = "_metRebateTransactionType"><c>TAMRebateTransactionType</c></param>
/// <returns><c>TAMRebateTransactionType</c></returns>
public TAMRebateTransactionType metParmRebateTransactionType(TAMRebateTransactionType _metRebateTransactionType = metRebateTransactionType)
{
    metRebateTransactionType = _metRebateTransactionType;
    return metRebateTransactionType;
}

/// <summary>
/// Filter transactions by the deal custom vendor account
/// Adding the vendor account range
/// </summary>
/// <param name = "_vendAccount">Vendor Account</param>
void metAddVendAccountRange()
{
    // When using line attributes for vendor rebates AccountCode will be set to All
    if (rebateTable.ModuleInventCustVend == ModuleInventCustVend::Vend
    &&  rebateTable.AccountCode          == TableGroupAll::All)
    {
        VendAccount vendAccount = rebateTable.TAMRebateDeal().METVendAccount;

        if (vendAccount)
        {
            // Force the filtering, we are only using line attributes (products) and not header attributes (vendor)
            SysQuery::findOrCreateRange(query.dataSourceTable(this.journalTable()), this.accountJourTableFieldId()).value(vendAccount);
        }
    }
}

/// <summary>
/// Adding the range for the external sales data processed flags based on the transaction types
/// </summary>
void metAddExternalSalesDataRange()
{
    if (metRebateTransactionType == TAMRebateTransactionType::Provision)
    {
        query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, ProvisionProcessed)).value(queryValue(NoYes::No));
    }
    else if (metRebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, RebateProcessed)).value(queryValue(NoYes::No));
    }
}
